JS_ADDITIONS = '/* DPH PHASE 2: progressive clues and genuine Strands boards */\nconst clueLevels=new Map();\n\nfunction dphClues(g,d){\n  if(!d || !g)return [];\n  if(Array.isArray(d.clues) && d.clues.length)return d.clues.filter(x=>typeof x===\'string\').slice(0,4);\n  if(Array.isArray(d.hint) && d.hint.length)return d.hint.filter(x=>typeof x===\'string\').slice(0,4);\n  const a=d.answer;\n  if(d.status!==\'verified\' || !a)return [];\n  const hints=[];\n  switch(g.id){\n    case \'wordle\': {\n      const w=String(a.value||\'\').toUpperCase();\n      if(w.length===5)hints.push(\'The answer has five letters.\',`It starts with ${w[0]}.`,`It ends with ${w[4]}.`);\n      break;\n    }\n    case \'strands\': {\n      if(a.theme)hints.push(`The theme is “${a.theme}”.`);\n      if(a.spangram)hints.push(`The spangram has ${a.spangram.length} letters.`);\n      if(a.paths?.[a.spangram]?.[0]){\n        const [r,c]=a.paths[a.spangram][0];\n        hints.push(`The spangram starts at row ${r}, column ${c}.`);\n      }else if(a.spangram)hints.push(`The spangram starts with ${a.spangram[0]}.`);\n      break;\n    }\n    case \'queens\':{\n      const cols=a.cols||[];\n      hints.push(`There are ${cols.length} queens: exactly one per row and column.`);\n      if(cols[0])hints.push(`The queen in row 1 belongs in column ${cols[0]}.`);\n      if(cols[1])hints.push(`The queen in row 2 belongs in column ${cols[1]}.`);\n      break;\n    }\n    case \'pinpoint\':{\n      const phrase=String(a.value||\'\').trim();\n      if(phrase){hints.push(\'Think of a shared category rather than a specific object.\');hints.push(`The category begins with “${phrase[0].toUpperCase()}”.`);}\n      break;\n    }\n    case \'crossclimb\':{\n      const w=a.words||[];\n      if(w.length){hints.push(`The ladder has ${w.length} words of ${w[0].length} letters.`);hints.push(`The first rung is ${w[0]}.`);if(w.length>2)hints.push(`The last rung is ${w[w.length-1]}.`);}\n      break;\n    }\n    case \'mathler\':{\n      const expr=String(a.value||a.equation||\'\');\n      const ops=[...new Set((expr.match(/[+*/-]/g)||[]))];\n      if(a.target!==undefined)hints.push(`Today\'s target is ${a.target}.`);\n      if(ops.length)hints.push(`The equation uses ${ops.length} distinct operator${ops.length===1?\'\':\'s\'}.`);\n      if(expr)hints.push(`The equation starts with ${expr[0]}.`);\n      break;\n    }\n    case \'sumplete\':{\n      if(a.kept?.[0])hints.push(`In row 1, ${a.kept[0].filter(Boolean).length} numbers are kept.`);\n      if(a.kept?.[0])hints.push(`The top-left number is ${a.kept[0][0]?\'kept\':\'removed\'}.`);\n      break;\n    }\n    case \'zip\':{\n      const checkpoints=a.checkpoints||[];\n      if(checkpoints.length)hints.push(`There are ${checkpoints.length} numbered checkpoints.`);\n      if(checkpoints[1])hints.push(`Checkpoint 2 is in row ${checkpoints[1][1]}, column ${checkpoints[1][2]}.`);\n      break;\n    }\n    case \'mini-sudoku\':{\n      if(a.rows?.[0]?.length){hints.push(\'Each row, column and 2×3 box contains 1–6.\');hints.push(`The top-left square is ${a.rows[0][0]}.`);}\n      break;\n    }\n    case \'tango\':{\n      if(a.rows?.[0]){hints.push(\'Each row and column has three suns and three moons.\');hints.push(`Row 1, column 1 is ${a.rows[0][0]===\'S\'?\'a sun\':\'a moon\'}.`);}\n      break;\n    }\n    case \'patches\':{\n      if(a.rects?.length){const sizes=a.rects.map(([r1,c1,r2,c2])=>(r2-r1+1)*(c2-c1+1));hints.push(`There are ${sizes.length} patches.`);hints.push(`The largest patch contains ${Math.max(...sizes)} cells.`);}\n      break;\n    }\n    case \'wend\':{\n      if(a.words?.length){hints.push(`There are ${a.words.length} hidden words.`);hints.push(`The shortest word is ${Math.min(...a.words.map(w=>w.length))} letters long.`);if(a.paths?.[0]?.[0])hints.push(`One route begins at row ${a.paths[0][0][0]}, column ${a.paths[0][0][1]}.`);}\n      break;\n    }\n    default:break;\n  }\n  return hints.slice(0,3);\n}\n\nfunction dphClueCard(g,d){\n  const hints=dphClues(g,d);\n  if(!hints.length)return \'\';\n  const shown=Math.min(clueLevels.get(g.id)||0,hints.length);\n  const lines=hints.slice(0,shown).map((h,i)=>`<p class="clue-line"><strong>Clue ${i+1}</strong> ${esc(h)}</p>`).join(\'\');\n  return `<section class="clue-panel" aria-label="Optional clues for ${esc(g.title)}">\n     <div class="clue-panel-head"><span>NEED A CLUE?</span><small>${shown} of ${hints.length} revealed</small></div>\n     ${lines}\n     <div class="clue-buttons">\n       ${shown<hints.length?`<button type="button" class="clue-next" data-clue="${esc(g.id)}" data-clue-action="next" aria-label="Reveal clue ${shown+1} for ${esc(g.title)}">Reveal clue ${shown+1} ↓</button>`:\'<span class="clue-complete">All clues revealed</span>\'}\n       ${shown>0?`<button type="button" class="clue-reset" data-clue="${esc(g.id)}" data-clue-action="reset">Hide clues</button>`:\'\'}\n     </div>\n     <p class="clue-disclaimer">Hints may be derived from the verified solution; they are not necessarily official puzzle clues.</p>\n  </section>`;\n}\n\nfunction dphStrands(a){\n  const theme=`<p class="answer-desc">THEME · ${esc(a.theme||\'\')}</p>`;\n  const list=`<p class="answer-desc">SPANGRAM</p><div class="answer-word">${esc(a.spangram||\'\')}</div><p class="answer-desc">THEME WORDS</p><div class="answer-tag-row">${(a.words||[]).map(w=>`<span class="answer-tag">${esc(w)}</span>`).join(\'\')}</div>`;\n  const grid=a.grid;\n  if(!Array.isArray(grid)||grid.length!==8||!grid.every(row=>Array.isArray(row)&&row.length===6))return theme+list+\'<p class="answer-desc">Original letter board is not confirmed for this date.</p>\';\n  const paths=a.paths||{}, words=[...(a.words||[]),a.spangram];\n  const point=([r,c])=>`${(c-.5)*100},${(r-.5)*100}`;\n  const lines=[], backgrounds=new Map();\n  const colours=[\'#b3e3f2\',\'#a3d7ef\',\'#bbe8ed\',\'#a6dce8\',\'#bddbee\',\'#9acfe5\',\'#bad5e9\'];\n  words.forEach((word,i)=>{\n    const path=paths[word];\n    if(!Array.isArray(path)||path.length!==word.length)return;\n    const tint=i===(words.length-1)?\'#ffca28\':colours[i%colours.length];\n    path.forEach(([r,c])=>backgrounds.set(`${r},${c}`,tint));\n    lines.push(`<polyline points="${path.map(point).join(\' \')}" stroke="${tint}" stroke-width="80" stroke-linecap="round" stroke-linejoin="round" fill="none"/>`);\n  });\n  const cells=grid.map((row,r)=>row.map((letter,c)=>{\n    const color=backgrounds.get(`${r+1},${c+1}`);\n    return `<div class="strands-cell" style="${color?\'background:\'+color+\';\':\'\'}" aria-label="Row ${r+1} column ${c+1}: ${esc(letter)}">${esc(letter)}</div>`;\n  }).join(\'\')).join(\'\');\n  return `${theme}<div class="strands-board" role="img" aria-label="Strands 6 column by 8 row letter board">${cells}${lines.length?`<svg class="strands-route-svg" viewBox="0 0 600 800" preserveAspectRatio="none" aria-hidden="true">${lines.join(\'\')}</svg>`:\'\'}</div>${list}<p class="answer-desc">${lines.length?\'Blue trails show theme words; gold shows the spangram.\':\'Letter board verified; complete paths are not yet confirmed.\'}</p>`;\n}\n\nfunction dphQueensPhase2(a){\n  const n=a?.cols?.length||0;\n  const regions=a.regions;\n  if(!n||!Array.isArray(regions)||regions.length!==n||!regions.every(row=>Array.isArray(row)&&row.length===n))return dphQueens(a);\n  const all=new Set(regions.flat().map(String));\n  const queens=new Set(a.cols.map((col,r)=>String(regions[r][col-1])));\n  if(all.size!==n||queens.size!==n)return dphQueens(a);\n  const edge=(r,c,side)=>{\n    const x=regions[r][c];\n    return side===\'top\'?(r===0||regions[r-1][c]!==x):side===\'right\'?(c===n-1||regions[r][c+1]!==x):side===\'bottom\'?(r===n-1||regions[r+1][c]!==x):(c===0||regions[r][c-1]!==x);\n  };\n  const cells=regions.map((row,r)=>row.map((zone,c)=>{\n    const queen=a.cols[r]===c+1;\n    const style=`background:${dphRegionColour(zone)}!important;border-top:${edge(r,c,\'top\')?2:0.5}px solid #26302a;border-right:${edge(r,c,\'right\')?2:0.5}px solid #26302a;border-bottom:${edge(r,c,\'bottom\')?2:0.5}px solid #26302a;border-left:${edge(r,c,\'left\')?2:0.5}px solid #26302a;`;\n    return `<div class="board-cell ${queen?\'queen\':\'\'}" style="${style}" aria-label="Row ${r+1} column ${c+1}: ${queen?\'queen\':\'empty\'} in region ${esc(zone)}">${queen?\'♛\':\'×\'}</div>`;\n  }).join(\'\')).join(\'\');\n  return `<div class="game-board queens-board p2-regions" style="grid-template-columns:repeat(${n},minmax(0,1fr))">${cells}</div><p class="answer-desc">Complete verified colour-region map; one queen in every region, row and column.</p>`;\n}\n'
BOARD_SUPPORT = '"""Validated optional board data for Daily Puzzle Hub.\n\nThe daily answer updater remains the authority for whether a puzzle is verified.\nWe never infer Queens region colours from queen coordinates.\n"""\nfrom __future__ import annotations\nimport json\nimport re\nfrom pathlib import Path\nfrom datetime import date\n\nNEIGHBOURS = [(r, c) for r in (-1,0,1) for c in (-1,0,1) if (r or c)]\n\n\ndef valid_strands(grid, paths, answer):\n    if (not isinstance(grid,list) or len(grid)!=8 or\n        any(not isinstance(row,list) or len(row)!=6 or any(not isinstance(x,str) or not re.fullmatch(\'[A-Z]\',x) for x in row) for row in grid)):\n        return False\n    if not isinstance(paths,dict):return False\n    words=[str(w).upper() for w in answer.get(\'words\',[])] + [str(answer.get(\'spangram\',\'\')).upper()]\n    if len(set(words))!=len(words) or set(paths)!=set(words):return False\n    used=set()\n    for word in words:\n        p=paths.get(word)\n        if not isinstance(p,list) or len(p)!=len(word):return False\n        spelling=\'\'\n        previous=None\n        for pos in p:\n            if not isinstance(pos,list) or len(pos)!=2:return False\n            r,c=pos\n            if type(r)!=int or type(c)!=int or not 1<=r<=8 or not 1<=c<=6 or (r,c) in used:return False\n            if previous and max(abs(previous[0]-r),abs(previous[1]-c))!=1:return False\n            used.add((r,c));spelling+=grid[r-1][c-1];previous=(r,c)\n        if spelling!=word:return False\n    if len(used)!=48:return False\n    span=paths[words[-1]]\n    rset={r for r,c in span};cset={c for r,c in span}\n    return (1 in rset and 8 in rset) or (1 in cset and 6 in cset)\n\n\ndef valid_queens_regions(regions, cols):\n    n=len(cols)\n    if (not isinstance(regions,list) or len(regions)!=n or\n        any(not isinstance(row,list) or len(row)!=n for row in regions)):\n        return False\n    labels={str(x) for row in regions for x in row}\n    if len(labels)!=n:return False\n    queen_labels=[]\n    for r,col in enumerate(cols):\n        if type(col)!=int or not 1<=col<=n:return False\n        queen_labels.append(str(regions[r][col-1]))\n    return len(set(queen_labels))==n\n\n\ndef find_strands_board(text):\n    """Use only a dated source\'s explicit 48-letter board; no synthesized grid."""\n    if not text:return None\n    candidates=[r\'\\bThe board\\b\\s*(.*?)\\s*\\bThe answers\\b\',\n                r\'\\bThe board\\b\\s*(.*?)\\s*\\bSpangram\\b\',\n                r\'\\bToday.s letter board\\b\\s*(.*?)\\s*\\bToday.s Strands answers\\b\']\n    for patt in candidates:\n        m=re.search(patt,text,re.I|re.S)\n        if not m:continue\n        letters=re.findall(r\'\\b[A-Z]\\b\',m.group(1).upper())\n        if len(letters)==48:\n            return [letters[r*6:(r+1)*6] for r in range(8)]\n    return None\n\n\ndef find_unique_paths(grid,answer):\n    """Only publish automatically derived word routes when the exact cover is unique."""\n    words=list(answer.get(\'words\',[]))+[answer.get(\'spangram\',\'\')]\n    words=[str(w).upper() for w in words]\n    if not grid or len(set(words))!=len(words) or sum(map(len,words))!=48:return None\n    candidates={}\n    for word in words:\n        paths=[]\n        def explore(r,c,i,used,path):\n            if len(paths)>1000:return\n            if i==len(word):paths.append(tuple(path));return\n            for dr,dc in NEIGHBOURS:\n                nr,nc=r+dr,c+dc\n                ix=nr*6+nc\n                if 0<=nr<8 and 0<=nc<6 and grid[nr][nc]==word[i] and not used>>ix&1:\n                    explore(nr,nc,i+1,used|(1<<ix),path+[ix])\n        for r in range(8):\n            for c in range(6):\n                if grid[r][c]==word[0]:explore(r,c,1,1<<(r*6+c),[r*6+c])\n        if not paths or len(paths)>1000:return None\n        if word==answer.get(\'spangram\',\'\').upper():\n            paths=[p for p in paths if (any(q//6==0 for q in p) and any(q//6==7 for q in p)) or (any(q%6==0 for q in p) and any(q%6==5 for q in p))]\n        if not paths:return None\n        candidates[word]=[(p,sum(1<<v for v in p)) for p in paths]\n    results=[]\n    def search(remaining,mask,selected):\n        if len(results)>=2:return\n        if not remaining:\n            if mask.bit_count()==48:results.append(selected.copy())\n            return\n        word=min(remaining,key=lambda w:len(candidates[w]))\n        for path,bits in candidates[word]:\n            if bits&mask:continue\n            selected[word]=[[k//6+1,k%6+1] for k in path]\n            search(remaining-{word},mask|bits,selected)\n            del selected[word]\n            if len(results)>=2:return\n    search(set(words),0,{})\n    if len(results)!=1:return None\n    return results[0] if valid_strands(grid,results[0],answer) else None\n\n\ndef enrich_daily_boards(day, data, root, fetch=None):\n    """Attach verified richer boards to an already-verified day\'s answer data."""\n    daystr=day.isoformat()\n    board_file=Path(root)/\'data\'/\'boards\'/f\'{daystr}.json\'\n    external={}\n    if board_file.exists():\n        try:external=json.loads(board_file.read_text(encoding=\'utf-8\'))\n        except (ValueError, OSError):pass\n    previous={}\n    prev_file=Path(root)/\'data\'/f\'{daystr}.json\'\n    if prev_file.exists():\n        try:\n            old=json.loads(prev_file.read_text(encoding=\'utf-8\'))\n            if old.get(\'date\')==daystr:previous=old.get(\'games\',{})\n        except (ValueError,OSError):pass\n    for game in (\'strands\',\'queens\'):\n        entry=data.get(\'games\',{}).get(game)\n        if not entry or entry.get(\'status\')!=\'verified\':continue\n        answer=entry.get(\'answer\') or {}\n        archived=(previous.get(game) or {}).get(\'answer\') or {}\n        curated=external.get(game) or {}\n        if game==\'strands\':\n            grid=curated.get(\'grid\')\n            paths=curated.get(\'paths\')\n            if not valid_strands(grid,paths,answer):\n                grid,paths=archived.get(\'grid\'),archived.get(\'paths\')\n            if valid_strands(grid,paths,answer):\n                answer[\'grid\'],answer[\'paths\']=grid,paths\n                print(\'  ✓ strands complete grid + paths\')\n                continue\n            # Future puzzles: attempt board import, but never make up a path.\n            if callable(fetch):\n                slug=day.strftime(\'%B\').lower()+\'-\'+str(day.day)+\'-\'+str(day.year)\n                url=f\'https://walkthroughs.net/strands-answers/{slug}\'\n                page=fetch(url)\n                if day.strftime(\'%B\').lower() in page.lower() and str(day.year) in page:\n                    grid=find_strands_board(re.sub(\'<[^>]+>\',\' \',page))\n                    if grid:\n                        paths=find_unique_paths(grid,answer)\n                        if paths and valid_strands(grid,paths,answer):\n                            answer[\'grid\'],answer[\'paths\']=grid,paths\n                            print(\'  ✓ strands grid + uniquely reconstructed paths\')\n                        else:\n                            answer[\'grid\']=grid\n                            print(\'  ~ strands board found; paths not uniquely verified\')\n        else:\n            regions=curated.get(\'regions\')\n            if not valid_queens_regions(regions,answer.get(\'cols\',[])):\n                regions=archived.get(\'regions\')\n            if valid_queens_regions(regions,answer.get(\'cols\',[])):\n                answer[\'regions\']=regions\n                print(\'  ✓ queens region map validated\')\n            else:\n                print(\'  ~ queens full region map unavailable; placements retained\')\n    for game,clues in (external.get(\'clues\') or {}).items():\n        entry=data.get(\'games\',{}).get(game)\n        if entry and entry.get(\'status\')==\'verified\' and isinstance(clues,list):\n            entry[\'clues\']=[str(x) for x in clues[:4] if isinstance(x,str) and x.strip()]\n'
CURATED_DAY = {'source': 'https://www.xfire.com/strands-hints-tool-7800/2026-11-02', 'strands': {'grid': [['E', 'U', 'S', 'I', 'F', 'P'], ['L', 'M', 'M', 'L', 'F', 'O'], ['D', 'I', 'E', 'C', 'N', 'T'], ['D', 'T', 'G', 'A', 'I', 'W'], ['A', 'D', 'N', 'T', 'K', 'O'], ['S', 'I', 'U', 'A', 'N', 'S'], ['R', 'O', 'E', 'R', 'E', 'I'], ['M', 'P', 'G', 'L', 'A', 'C']], 'paths': {'CLIFF': [[3, 4], [2, 4], [1, 4], [1, 5], [2, 5]], 'GLACIER': [[8, 3], [8, 4], [8, 5], [8, 6], [7, 6], [7, 5], [7, 4]], 'PEAK': [[8, 2], [7, 3], [6, 4], [5, 5]], 'RIDGE': [[7, 1], [6, 2], [5, 2], [4, 3], [3, 3]], 'SADDLE': [[6, 1], [5, 1], [4, 1], [3, 1], [2, 1], [1, 1]], 'SNOW': [[6, 6], [6, 5], [5, 6], [4, 6]], 'SUMMIT': [[1, 3], [1, 2], [2, 3], [2, 2], [3, 2], [4, 2]], 'MOUNTAINTOP': [[8, 1], [7, 2], [6, 3], [5, 3], [5, 4], [4, 4], [4, 5], [3, 5], [3, 6], [2, 6], [1, 6]]}}, 'clues': {'queens': ['The lavender region is only one cell, so its queen is forced.', 'The green region lies in row 2. Try eliminating other colours from that row.', 'The queen in row 2 belongs in column 2.'], 'pinpoint': ['The first revealed word is BODY.', 'The second revealed word is GREETING.', 'The third revealed word is ADDRESS.']}}

root=Path.cwd()
jsfile=root/'app.js';cssfile=root/'style.css';htmlfile=root/'index.html';upfile=root/'scripts'/'update.py'
for p in (jsfile,cssfile,htmlfile,upfile):
    if not p.is_file():raise SystemExit(f'Missing {p}. Run from your Daily-Puzzle-Hub repository root.')
js=jsfile.read_text(encoding='utf-8')
css=cssfile.read_text(encoding='utf-8')
html=htmlfile.read_text(encoding='utf-8')
up=upfile.read_text(encoding='utf-8')

if '/* DPH PHASE 2: progressive clues and genuine Strands boards */' in js:
    raise SystemExit('Phase 2 already installed; no changes made.')

required={
 'Card function':('function cardHTML(g){',js),
 'Answer renderer':('function answerHTML(a,g){',js),
 'Card clue slot':('${hints}${answer}',js),
 'Card metadata':('const other=g.id=',js),
 'Date reset':('selectedDay=day;revealed.clear();',js),
 'Reveal handler':("const btn=event.target.closest('[data-reveal]');",js),
 'Strands case':("case 'strands':return",js),
 'Queens case':("case 'queens':return",js),
 'Updater hook':('    update_linkedin(day,obj)',up)
}
missing=[name for name,(needle,data) in required.items() if data.count(needle)!=1]
if missing:raise SystemExit('Current code differs from expected template: '+', '.join(missing)+'; no changes made.')

js=js.replace('function cardHTML(g){',JS_ADDITIONS+'\nfunction cardHTML(g){',1)
js=js.replace('selectedDay=day;revealed.clear();','selectedDay=day;revealed.clear();clueLevels.clear();',1)
js=js.replace('const other=g.id=','const clueSection=dphClueCard(g,d);const other=g.id=',1)
js=js.replace('<div class="card-actions">','${clueSection}<div class="card-actions">',1)
# Retire the old all-at-once hint dropdown; the clues are progressive now.
