handler=(
 "const cb=event.target.closest('[data-clue]');"
 "if(cb){const id=cb.dataset.clue;const g=GAMES.find(g=>g.id===id);"
 "const max=dphClues(g,dayData?.games?.[id]).length;"
 "if(cb.dataset.clueAction==='reset')clueLevels.delete(id);"
 "else clueLevels.set(id,Math.min(max,(clueLevels.get(id)||0)+1));"
 "render();return;}"
)
