# Update both assets with new fixed URLs so cached JS never hides the work.
for filename in ('app.js','style.css'):
    pattern=r'''((?:src|href)=["'])([^"']*'''+re.escape(filename)+r''')(?:\?[^"']*)?(["'])'''
    html,count=re.subn(pattern,lambda m:m.group(1)+m.group(2)+'?v=phase2-clues-strands-1'+m.group(3),html)
    if count!=1:raise SystemExit(f'{filename} reference count {count}, expected 1; no files changed.')

up=up.replace('    update_linkedin(day,obj)',
              '    update_linkedin(day,obj)\n'
              '    from phase2_boards import enrich_daily_boards\n'
              '    enrich_daily_boards(day,obj,ROOT,fetch=fetch)',1)

# Validate curated board against the verified answer, without network access.
sys.path.insert(0,str(root/'scripts'))
# Write to temporary names first; the actual day-file is touched only after validation.
board_file=root/'data'/'boards'/'2026-11-02.json'
board_file.parent.mkdir(parents=True,exist_ok=True)
board_file.write_text(json.dumps(CURATED_DAY,indent=2)+'\n',encoding='utf-8')
support_path=root/'scripts'/'phase2_boards.py'
support_path.write_text(BOARD_SUPPORT,encoding='utf-8')
from phase2_boards import valid_strands, enrich_daily_boards
existing=root/'data'/'2026-11-02.json'
if existing.exists():
    d=json.loads(existing.read_text(encoding='utf-8'))
    entry=d.get('games',{}).get('strands',{})
    if entry.get('status')=='verified':
        a=entry.get('answer') or {}
        curated=CURATED_DAY['strands']
        if not valid_strands(curated['grid'],curated['paths'],a):
            raise SystemExit('Curated Strands grid does not match saved answer. Nothing published; inspect the day file.')
        enrich_daily_boards(date.fromisoformat('2026-11-02'),d,root,fetch=None)
        existing.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
        print('Updated 2026-11-02.json with verified Strands grid, routes and dated clues')

jsfile.write_text(js,encoding='utf-8')
cssfile.write_text(css,encoding='utf-8')
htmlfile.write_text(html,encoding='utf-8')
upfile.write_text(up,encoding='utf-8')
print('Phase 2 installed: progressive clues, Strands board and Queens region support.')
print('Next: node --check app.js && python scripts/validate.py && python scripts/embed.py')
